let unlocked = false;

/** Browsers block audio until the user interacts with the page. Call on click/tap. */
export async function unlockAudioPlayback(): Promise<void> {
  if (unlocked || typeof window === "undefined") return;

  try {
    const silent = new Audio(
      "data:audio/mp3;base64,"
    );
    silent.volume = 0.01;
    await silent.play();
    unlocked = true;
  } catch {
    // still try on next interaction
  }
}

export function isAudioUnlocked() {
  return unlocked;
}
